import React from "react";
import { Link, useNavigate } from "react-router-dom";
import "./Header.css";

export default function Header() {
  const navigate = useNavigate();
  return (
    <header className="header-artisa">
      <div className="header-content">
        <div className="header-logo-nombre">
          <img src="/logo-artisa.png" alt="Logo Artisa" className="header-logo" />
          <span className="header-nombre">ARTISA</span>
        </div>
        <nav className="header-nav">
          <Link to="/">Inicio</Link>
          <Link to="/catalogo">Catalogo</Link>
          <Link to="/blog">Blog</Link>
          <button className="header-login-btn" onClick={() => navigate("/login")}>Iniciar sesión</button>
        </nav>
      </div>
    </header>
  );
}
